CREATE OR REPLACE FUNCTION ms_b1_design.b1b_actor(h bytea, csrf bytea DEFAULT NULL::bytea, mutation boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE s ms_b1_design.auth_session; u ms_b1_design.app_user; user_id uuid;
BEGIN
  SELECT x.user_id INTO user_id FROM ms_b1_design.auth_session x WHERE token_hash=h;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='MS401', MESSAGE='Unauthenticated'; END IF;
  -- Same user -> session lock order as offline rotation; avoid fixation/revocation deadlocks.
  SELECT * INTO u FROM ms_b1_design.app_user WHERE id=user_id FOR SHARE;
  SELECT * INTO s FROM ms_b1_design.auth_session WHERE token_hash=h FOR UPDATE;
  IF NOT FOUND OR s.business_id IS NULL OR s.revoked_at IS NOT NULL OR s.expires_at<=clock_timestamp()
    OR s.idle_expires_at IS NULL OR s.idle_expires_at<=clock_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE='MS401', MESSAGE='Unauthenticated';
  END IF;
  PERFORM 1 FROM ms_b1_design.business WHERE id=s.business_id AND archived_at IS NULL FOR SHARE;
  IF NOT FOUND OR u.status IS DISTINCT FROM 'ACTIVE' OR u.archived_at IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='MS401', MESSAGE='Unauthenticated';
  END IF;
  IF mutation AND (csrf IS NULL OR s.csrf_hash IS DISTINCT FROM csrf) THEN
    RAISE EXCEPTION USING ERRCODE='MS403', MESSAGE='Forbidden';
  END IF;
  -- Lock active membership/role/permission evidence until transaction end.
  PERFORM 1 FROM ms_b1_design.user_role_assignment a JOIN ms_b1_design.role r
    ON r.business_id=a.business_id AND r.id=a.role_id
    WHERE a.business_id=s.business_id AND a.user_id=s.user_id AND a.revoked_at IS NULL
    AND a.archived_at IS NULL AND r.archived_at IS NULL FOR SHARE OF a,r;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='MS403', MESSAGE='Forbidden'; END IF;
  PERFORM 1 FROM ms_b1_design.role_permission rp JOIN ms_b1_design.permission p ON p.id=rp.permission_id
    WHERE rp.business_id=s.business_id AND rp.archived_at IS NULL AND p.archived_at IS NULL FOR SHARE OF rp,p;
  UPDATE ms_b1_design.auth_session SET last_seen_at=clock_timestamp(),
    idle_expires_at=least(expires_at,clock_timestamp()+interval '15 minutes'),updated_at=clock_timestamp()
    WHERE id=s.id;
  RETURN jsonb_build_object('userId',s.user_id,'businessId',s.business_id,'sessionId',s.id);
END $function$

CREATE OR REPLACE FUNCTION ms_b1_design.b1b_command(h bytea, csrf bytea, kind text, entity uuid, branchid uuid, expected bigint, idem text, requestid uuid, d jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a jsonb;bid uuid;
BEGIN
 a:=ms_b1_design.b1b_actor(h,csrf,true);bid:=(a->>'businessId')::uuid;
 PERFORM ms_b1_design.b2b_lock(bid);
 IF kind<>'session' AND (EXISTS(SELECT 1 FROM ms_b1_design.staff_schedule_rule WHERE business_id=bid)
 OR EXISTS(SELECT 1 FROM ms_b1_design.branch_working_hours WHERE business_id=bid)
 OR EXISTS(SELECT 1 FROM ms_b1_design.staff_shift WHERE business_id=bid)) THEN PERFORM ms_b1_design.b2b_fail('CALENDAR_RECONCILIATION_REQUIRED');END IF;
 RETURN ms_b1_design.b2b_legacy_command(h,csrf,kind,entity,branchid,expected,idem,requestid,d);
END $function$

CREATE OR REPLACE FUNCTION ms_b1_design.b1b_read(h bytea, kind text, target_branch uuid, page_size integer, page_offset integer, sort_order text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a jsonb; bid uuid; permission_key text; items jsonb;
BEGIN
 a:=ms_b1_design.b1b_actor(h);bid:=(a->>'businessId')::uuid;
 IF kind NOT IN ('business','branch','service','offering') OR kind IS NULL OR page_size NOT BETWEEN 1 AND 100
 OR page_offset NOT BETWEEN 0 AND 10000 OR sort_order NOT IN ('asc','desc') OR page_size IS NULL OR page_offset IS NULL OR sort_order IS NULL THEN
 RAISE EXCEPTION USING ERRCODE='MS422', MESSAGE='Invalid query'; END IF;
 permission_key:=CASE kind WHEN 'business' THEN 'business.read' WHEN 'branch' THEN 'branch.read' WHEN 'service' THEN 'catalog.read' ELSE 'offering.read' END;
 IF kind='offering' THEN
  IF NOT ms_b1_design.b1b_can(a,permission_key,target_branch) THEN RAISE EXCEPTION USING ERRCODE='MS403', MESSAGE='Forbidden'; END IF;
  IF NOT EXISTS(SELECT 1 FROM ms_b1_design.branch WHERE business_id=bid AND id=target_branch AND archived_at IS NULL) THEN
   RAISE EXCEPTION USING ERRCODE='MS404', MESSAGE='Not found'; END IF;
 ELSIF NOT ms_b1_design.b1b_can(a,permission_key,NULL) AND NOT(kind='branch' AND EXISTS(
   SELECT 1 FROM ms_b1_design.branch b WHERE b.business_id=bid AND b.archived_at IS NULL AND ms_b1_design.b1b_can(a,permission_key,b.id))) THEN
  RAISE EXCEPTION USING ERRCODE='MS403', MESSAGE='Forbidden';
 END IF;
 PERFORM set_config('ms.business_id',bid::text,true);
 SELECT coalesce(jsonb_agg(v ORDER BY ord),'[]'::jsonb) INTO items FROM (
  SELECT ms_b1_design.b1b_view(kind,value) v,row_number() OVER(ORDER BY
    CASE WHEN sort_order='asc' THEN value->>'code' END ASC,
    CASE WHEN sort_order='desc' THEN value->>'code' END DESC,value->>'id') ord FROM (
    SELECT to_jsonb(b) value FROM ms_b1_design.business b WHERE kind='business' AND b.id=bid AND b.archived_at IS NULL
    UNION ALL SELECT to_jsonb(b) FROM ms_b1_design.branch b WHERE kind='branch' AND b.business_id=bid AND b.archived_at IS NULL AND ms_b1_design.b1b_can(a,permission_key,b.id)
    UNION ALL SELECT to_jsonb(s) FROM ms_b1_design.service s WHERE kind='service' AND s.business_id=bid AND s.archived_at IS NULL
    UNION ALL SELECT to_jsonb(o) FROM ms_b1_design.branch_service_offering o WHERE kind='offering' AND o.business_id=bid AND o.branch_id=target_branch AND o.archived_at IS NULL
  ) all_rows ORDER BY ord LIMIT page_size OFFSET page_offset
 ) projected;
 RETURN jsonb_build_object('items',items,'limit',page_size,'offset',page_offset);
END $function$

CREATE OR REPLACE FUNCTION ms_b1_design.b1b_validate(kind text, d jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE allowed text[]; k text; n text;
BEGIN
 IF jsonb_typeof(d) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='MS422', MESSAGE='Invalid DTO'; END IF;
 allowed:=CASE kind WHEN 'branch' THEN ARRAY['code','displayName','address','timeZone','active','bookable']
 WHEN 'service' THEN ARRAY['code','displayName','description','active']
 WHEN 'offering' THEN ARRAY['serviceId','active','price','durationMinutes','bufferBeforeMinutes','bufferAfterMinutes','eligibleStaffIds','resourcesConfirmed','resourceRequirements']
 WHEN 'session' THEN ARRAY[]::text[] ELSE NULL END;
 IF allowed IS NULL OR NOT(d ?& allowed) OR EXISTS(SELECT 1 FROM jsonb_object_keys(d) x WHERE NOT(x=ANY(allowed))) THEN
 RAISE EXCEPTION USING ERRCODE='MS422', MESSAGE='Unknown or missing field'; END IF;
 IF kind='session' THEN RETURN; END IF;
 IF jsonb_typeof(d->'active')<>'boolean' THEN RAISE EXCEPTION USING ERRCODE='MS422', MESSAGE='Invalid active'; END IF;
 IF kind IN ('branch','service') THEN
  IF jsonb_typeof(d->'code')<>'string' OR (d->>'code') !~ '^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$'
   OR jsonb_typeof(d->'displayName')<>'string' OR length(btrim(d->>'displayName')) NOT BETWEEN 1 AND 200 THEN
   RAISE EXCEPTION USING ERRCODE='MS422', MESSAGE='Invalid code or name'; END IF;
  k:=CASE kind WHEN 'branch' THEN 'address' ELSE 'description' END;
  IF jsonb_typeof(d->k) NOT IN ('null','string') OR length(d->>k)>(CASE kind WHEN 'branch' THEN 1000 ELSE 2000 END) THEN
   RAISE EXCEPTION USING ERRCODE='MS422', MESSAGE='Invalid text'; END IF;
 END IF;
 IF kind='branch' AND (d->'bookable' IS DISTINCT FROM 'false'::jsonb OR jsonb_typeof(d->'timeZone')<>'string' OR NOT EXISTS
  (SELECT 1 FROM pg_catalog.pg_timezone_names WHERE name=d->>'timeZone' AND name !~ '^(posix|right)/' AND (name='UTC' OR position('/' IN name)>0))) THEN
  RAISE EXCEPTION USING ERRCODE='MS422', MESSAGE='Branch not bookable in B1B or invalid IANA timezone'; END IF;
 IF kind='offering' THEN
  IF d->'active' IS DISTINCT FROM 'false'::jsonb OR d->'resourcesConfirmed' IS DISTINCT FROM 'false'::jsonb
   OR d->'eligibleStaffIds' IS DISTINCT FROM '[]'::jsonb OR d->'resourceRequirements' IS DISTINCT FROM '[]'::jsonb
   OR jsonb_typeof(d->'serviceId')<>'string' OR (d->>'serviceId') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
   RAISE EXCEPTION USING ERRCODE='MS422', MESSAGE='Inactive unverified offering required'; END IF;
  FOREACH k IN ARRAY ARRAY['durationMinutes','bufferBeforeMinutes','bufferAfterMinutes'] LOOP
   n:=d->>k;
   IF jsonb_typeof(d->k)<>'null' AND (jsonb_typeof(d->k)<>'number' OR n !~ '^(0|[1-9][0-9]{0,9})$' OR n::numeric>2147483647 OR (k='durationMinutes' AND n::numeric=0)) THEN
    RAISE EXCEPTION USING ERRCODE='MS422', MESSAGE='Invalid duration or buffer'; END IF;
  END LOOP;
  IF d->'price'<>'null'::jsonb THEN
   IF jsonb_typeof(d->'price')<>'object' OR NOT(d->'price' ?& ARRAY['amountRial','currency','unitVersion'])
   OR (SELECT count(*) FROM jsonb_object_keys(d->'price'))<>3 OR d->'price'->>'currency'<>'IRR' OR d->'price'->>'unitVersion'<>'IRR_RIAL_V1'
   OR jsonb_typeof(d->'price'->'amountRial')<>'string' OR (d->'price'->>'amountRial') !~ '^(0|[1-9][0-9]*0)$'
   OR length(d->'price'->>'amountRial')>19 OR (d->'price'->>'amountRial')::numeric>9223372036854775807 THEN
    RAISE EXCEPTION USING ERRCODE='MS422', MESSAGE='Invalid money'; END IF;
  END IF;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION ms_b1_design.b1b_view(kind text, value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE result jsonb;
BEGIN
 result:=jsonb_build_object('id',value->'id','version',value->>'row_version');
 IF kind='business' THEN RETURN result||jsonb_build_object('brandName',value->'brand_name','legalName',value->'legal_name','currency',value->'currency_code'); END IF;
 IF kind IN ('branch','service') THEN
  result:=result||jsonb_build_object('code',value->'code','displayName',value->'display_name','active',value->'active');
  IF kind='service' THEN RETURN result||jsonb_build_object('description',value->'description'); END IF;
  RETURN result||jsonb_build_object('address',value->'address','timeZone',value->'time_zone','bookable',value->'bookable','configurationVersion',value->>'configuration_version');
 END IF;
 RETURN result||jsonb_build_object('branchId',value->'branch_id','serviceId',value->'service_id','active',value->'active',
  'price',CASE WHEN value->>'price_rial' IS NULL THEN NULL ELSE jsonb_build_object('amountRial',value->>'price_rial','currency','IRR','unitVersion','IRR_RIAL_V1') END,
  'durationMinutes',value->'duration_minutes','bufferBeforeMinutes',value->'buffer_before_minutes','bufferAfterMinutes',value->'buffer_after_minutes',
  'configurationVersion',value->>'configuration_version','resourcesConfirmed',value->'resources_confirmed','eligibleStaffIds',coalesce((SELECT jsonb_agg(DISTINCT e.staff_id ORDER BY e.staff_id) FROM ms_b1_design.offering_staff_eligibility e JOIN ms_b1_design.staff s ON s.business_id=e.business_id AND s.id=e.staff_id JOIN ms_b1_design.staff_service_eligibility q ON q.business_id=e.business_id AND q.id=e.qualification_id JOIN ms_b1_design.staff_branch_assignment m ON m.business_id=e.business_id AND m.id=e.assignment_id WHERE e.business_id=(value->>'business_id')::uuid AND e.offering_id=(value->>'id')::uuid AND e.active AND e.archived_at IS NULL AND s.active AND s.archived_at IS NULL AND q.active AND q.verified_at IS NOT NULL AND q.archived_at IS NULL AND m.active AND m.voided_at IS NULL AND m.archived_at IS NULL AND m.membership_period @> ((statement_timestamp() AT TIME ZONE (SELECT b.time_zone FROM ms_b1_design.branch b WHERE b.business_id=e.business_id AND b.id=e.branch_id))::date)),'[]'::jsonb),
  'resourceRequirements',coalesce((SELECT jsonb_agg(jsonb_build_object('kind',r.resource_kind,'quantity',r.quantity) ORDER BY r.resource_kind)
   FROM ms_b1_design.offering_resource_requirement r WHERE r.business_id=(value->>'business_id')::uuid
   AND r.offering_id=(value->>'id')::uuid AND r.archived_at IS NULL),'[]'::jsonb));
END $function$

CREATE OR REPLACE FUNCTION ms_b1_design.b2a_revision_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE before_row jsonb; after_row jsonb; identity_keys text[]; key text;
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='b2a_history_retained',MESSAGE='Archive history instead of deleting';
 END IF;
 before_row:=to_jsonb(OLD);after_row:=to_jsonb(NEW);
 IF NEW.row_version<>OLD.row_version+1 THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='b2a_next_row_version',MESSAGE='Exact next row version required';
 END IF;
 identity_keys:=ARRAY['id','business_id','created_at','created_by'];
 CASE TG_TABLE_NAME
 WHEN 'resource' THEN identity_keys:=identity_keys||ARRAY['kind','branch_id'];
 WHEN 'staff' THEN identity_keys:=identity_keys||ARRAY['resource_id','resource_kind'];
  IF OLD.user_id IS NOT NULL AND NEW.user_id IS DISTINCT FROM OLD.user_id THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='b2a_identity_frozen',MESSAGE='Linked staff user cannot change'; END IF;
 WHEN 'staff_branch_assignment' THEN
  identity_keys:=identity_keys||ARRAY['staff_id','branch_id','valid_from'];
  IF OLD.valid_to IS NOT NULL AND NEW.valid_to IS DISTINCT FROM OLD.valid_to THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='b2a_membership_end_frozen',MESSAGE='Closed membership remains historical'; END IF;
  IF OLD.voided_at IS NOT NULL AND (NEW.voided_at IS DISTINCT FROM OLD.voided_at OR NEW.void_reason IS DISTINCT FROM OLD.void_reason) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='b2a_void_frozen',MESSAGE='Void correction cannot be silently undone'; END IF;
 WHEN 'staff_service_eligibility' THEN identity_keys:=identity_keys||ARRAY['staff_id','service_id'];
 WHEN 'offering_staff_eligibility' THEN identity_keys:=identity_keys||ARRAY['offering_id','branch_id','service_id','staff_id','assignment_id','qualification_id'];
 WHEN 'staff_shift' THEN identity_keys:=identity_keys||ARRAY['staff_id','branch_id','assignment_id'];
 WHEN 'availability_configuration' THEN
  identity_keys:=identity_keys||ARRAY['branch_id'];
  IF NEW.configuration_version<>OLD.configuration_version+1 THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='b2a_next_configuration_version',MESSAGE='Exact next configuration version required'; END IF;
 ELSE NULL;
 END CASE;
 FOREACH key IN ARRAY identity_keys LOOP
  IF after_row->key IS DISTINCT FROM before_row->key THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='b2a_identity_frozen',MESSAGE='Stable identity or reference cannot change'; END IF;
 END LOOP;
 IF OLD.archived_at IS NOT NULL AND NEW.archived_at IS DISTINCT FROM OLD.archived_at THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='b2a_archive_frozen',MESSAGE='Historical archive cannot be silently undone'; END IF;
 -- Rules/exceptions are immutable revisions. Published instants never move in place.
 -- Archive old evidence and insert a distinct successor; no automatic publication.
 IF TG_TABLE_NAME IN ('branch_working_hours','staff_schedule_rule','staff_time_off','branch_closure')
  OR (TG_TABLE_NAME='staff_shift' AND (before_row->>'published')::boolean) THEN
  -- Stored generated fields are not populated in NEW during a BEFORE trigger.
  -- Their source columns remain frozen; PostgreSQL itself forbids overriding them.
  IF (after_row-ARRAY['row_version','updated_at','archived_at','working_period','membership_period']) IS DISTINCT FROM
     (before_row-ARRAY['row_version','updated_at','archived_at','working_period','membership_period']) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='b2a_revision_immutable',MESSAGE='Create a new schedule or exception revision'; END IF;
 END IF;
 NEW.updated_at:=clock_timestamp();RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION ms_b1_design.b2b_check_shift(bid uuid, sid uuid, branchid uuid, assignmentid uuid, ruleid uuid, day date, sm integer, em integer, zone text, st timestamp with time zone, en timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE r ms_b1_design.staff_schedule_rule; m ms_b1_design.staff_branch_assignment; q ms_b1_design.staff_service_eligibility;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM ms_b1_design.branch WHERE business_id=bid AND id=branchid AND active AND archived_at IS NULL AND time_zone=zone)
 OR NOT EXISTS(SELECT 1 FROM ms_b1_design.staff s JOIN ms_b1_design.resource u ON u.business_id=s.business_id AND u.id=s.resource_id
 WHERE s.business_id=bid AND s.id=sid AND s.active AND s.archived_at IS NULL AND u.active AND u.archived_at IS NULL AND u.kind='STAFF') THEN
 PERFORM ms_b1_design.b2b_fail('INACTIVE_CONTEXT'); END IF;
 SELECT * INTO m FROM ms_b1_design.staff_branch_assignment WHERE business_id=bid AND id=assignmentid AND staff_id=sid AND branch_id=branchid;
 IF NOT FOUND OR NOT m.active OR m.archived_at IS NOT NULL OR m.voided_at IS NOT NULL OR NOT(m.membership_period @> day)
 OR st < ms_b1_design.b2b_local_instant(m.valid_from::timestamp,zone,'reject') OR (m.valid_to IS NOT NULL AND en > ms_b1_design.b2b_local_instant(m.valid_to::timestamp,zone,'reject')) THEN
 PERFORM ms_b1_design.b2b_fail('MEMBERSHIP_NOT_COVERED'); END IF;
 SELECT * INTO r FROM ms_b1_design.staff_schedule_rule WHERE business_id=bid AND id=ruleid AND staff_id=sid AND branch_id=branchid AND assignment_id=assignmentid;
 IF NOT FOUND OR r.archived_at IS NOT NULL OR r.iso_weekday<>extract(isodow FROM day) OR r.start_minute<>sm OR r.end_minute<>em OR
 day<r.valid_from OR (r.valid_to IS NOT NULL AND day>=r.valid_to) OR r.qualification_id IS NULL THEN PERFORM ms_b1_design.b2b_fail('RULE_NOT_APPLICABLE'); END IF;
 SELECT * INTO q FROM ms_b1_design.staff_service_eligibility WHERE business_id=bid AND id=r.qualification_id AND staff_id=sid AND service_id=r.service_id;
 IF NOT FOUND OR NOT q.active OR q.verified_at IS NULL OR q.archived_at IS NOT NULL OR NOT EXISTS
 (SELECT 1 FROM ms_b1_design.service WHERE business_id=bid AND id=q.service_id AND active AND archived_at IS NULL) THEN PERFORM ms_b1_design.b2b_fail('QUALIFICATION_REQUIRED'); END IF;
 IF r.offering_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM ms_b1_design.offering_staff_eligibility e JOIN ms_b1_design.branch_service_offering o
 ON o.business_id=e.business_id AND o.id=e.offering_id WHERE e.business_id=bid AND e.staff_id=sid AND e.branch_id=branchid AND e.assignment_id=assignmentid
 AND e.offering_id=r.offering_id AND e.qualification_id=q.id AND e.active AND e.archived_at IS NULL AND o.archived_at IS NULL) THEN
 PERFORM ms_b1_design.b2b_fail('OFFERING_ELIGIBILITY_REQUIRED'); END IF;
 -- Every local minute must be covered by reviewed effective opening segments.
 IF EXISTS(SELECT 1 FROM generate_series(sm,em-1) minute WHERE NOT EXISTS(SELECT 1 FROM ms_b1_design.branch_working_hours h
 WHERE h.business_id=bid AND h.branch_id=branchid AND h.archived_at IS NULL AND h.iso_weekday=extract(isodow FROM day)
 AND day>=h.valid_from AND (h.valid_to IS NULL OR day<h.valid_to) AND minute>=h.start_minute AND minute<h.end_minute)) THEN
 PERFORM ms_b1_design.b2b_fail('OUTSIDE_OPENING_HOURS'); END IF;
 IF EXISTS(SELECT 1 FROM ms_b1_design.staff_time_off x WHERE x.business_id=bid AND x.staff_id=sid AND x.archived_at IS NULL
 AND x.review_status IN ('APPROVED','LEGACY_UNREVIEWED') AND x.starts_at<en AND x.ends_at>st
 AND NOT EXISTS(SELECT 1 FROM ms_b1_design.staff_time_off n WHERE n.business_id=bid AND n.supersedes_id=x.id)) THEN
 PERFORM ms_b1_design.b2b_fail('TIME_OFF_CONFLICT'); END IF;
 IF EXISTS(SELECT 1 FROM ms_b1_design.branch_closure x WHERE x.business_id=bid AND x.branch_id=branchid AND x.archived_at IS NULL
 AND x.review_status IN ('APPROVED','LEGACY_UNREVIEWED') AND x.starts_at<en AND x.ends_at>st
 AND NOT EXISTS(SELECT 1 FROM ms_b1_design.branch_closure n WHERE n.business_id=bid AND n.supersedes_id=x.id)) THEN
 PERFORM ms_b1_design.b2b_fail('CLOSURE_CONFLICT'); END IF;
 IF EXISTS(SELECT 1 FROM ms_b1_design.staff_shift x WHERE x.business_id=bid AND x.staff_id=sid AND x.published AND x.archived_at IS NULL AND x.branch_id<>branchid) THEN
 PERFORM ms_b1_design.b2b_fail('TRANSFER_CONFIGURATION_REQUIRED'); END IF;
 IF EXISTS(SELECT 1 FROM ms_b1_design.staff_shift x WHERE x.staff_id=sid AND x.published AND x.archived_at IS NULL AND x.starts_at<en AND x.ends_at>st) THEN
 PERFORM ms_b1_design.b2b_fail('SHIFT_OVERLAP'); END IF;
END $function$

CREATE OR REPLACE FUNCTION ms_b1_design.b2b_command(h bytea, csrf bytea, op text, branchid uuid, entity uuid, expected bigint, idem text, requestid uuid, d jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a jsonb;bid uuid;uid uuid;permission text;global_command boolean;route text;digest bytea;prior ms_b1_design.idempotency_record;
 version bigint; target uuid; sid uuid;rid uuid;serviceid uuid;assignmentid uuid;qualificationid uuid;offeringid uuid;
 saved jsonb;result jsonb;items jsonb:='[]';part jsonb;day date;sm int;em int;zone text;st timestamptz;en timestamptz;
 r ms_b1_design.staff_schedule_rule;m ms_b1_design.staff_branch_assignment;ruleversion bigint;plan uuid;ids uuid[];n int;
BEGIN
 a:=ms_b1_design.b1b_actor(h,csrf,true);bid:=(a->>'businessId')::uuid;uid:=(a->>'userId')::uuid;
 PERFORM ms_b1_design.b2b_validate(op,d);
 global_command:=op IN ('staff.create','staff.update','staff.link','qualification.set');
 IF global_command AND branchid IS NOT NULL OR NOT global_command AND branchid IS NULL THEN PERFORM ms_b1_design.b2b_fail('INVALID_SCOPE','MS422'); END IF;
 permission:=CASE WHEN op LIKE 'staff.%' THEN CASE WHEN op='staff.link' THEN 'staff.link' ELSE 'staff.manage' END
 WHEN op='qualification.set' THEN 'staff.qualify' WHEN op LIKE 'assignment.%' THEN 'staff.manage'
 WHEN op LIKE 'resource.%' THEN 'resource.manage' WHEN op='hours.replace' THEN 'branchhours.manage'
 WHEN op IN ('schedule.publish','schedule.withdraw') THEN 'schedule.publish'
 WHEN op IN ('timeoff.review','closure.review') THEN 'timeoff.approve' ELSE 'schedule.manage' END;
 IF NOT ms_b1_design.b1b_can(a,permission,branchid) THEN PERFORM ms_b1_design.b2b_fail('FORBIDDEN','MS403'); END IF;
 IF expected IS NULL OR expected<1 THEN PERFORM ms_b1_design.b2b_fail('VERSION_REQUIRED','MS412'); END IF;
 IF idem IS NULL OR idem !~ '^[A-Za-z0-9_-]{16,128}$' OR requestid IS NULL THEN PERFORM ms_b1_design.b2b_fail('INVALID_HEADERS','MS422'); END IF;
 PERFORM ms_b1_design.b2b_lock(bid);
 IF branchid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM ms_b1_design.branch WHERE business_id=bid AND id=branchid AND archived_at IS NULL) THEN PERFORM ms_b1_design.b2b_fail('NOT_FOUND','MS404'); END IF;
 route:='b2b:'||op||':'||coalesce(branchid::text,'global')||':'||coalesce(entity::text,'new');
